#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <fstream>
#include <vector>
#include <chrono>
#include <algorithm>
#include "rkllm.h"
static std::vector<float> hidden; static int g_tokens=0,g_dim=0; static float g_prefill=0,g_mem=0;
static int cb(RKLLMResult* r, void*, LLMCallState state){if(state==RKLLM_RUN_NORMAL&&r&&r->last_hidden_layer.hidden_states){g_tokens=r->last_hidden_layer.num_tokens;g_dim=r->last_hidden_layer.embd_size;hidden.assign(r->last_hidden_layer.hidden_states,r->last_hidden_layer.hidden_states+(size_t)g_tokens*g_dim);g_prefill=r->perf.prefill_time_ms;g_mem=r->perf.memory_usage_mb;}return 0;}
static inline float lin(const float*w,const float*h,const float*b){float x=*b;for(int i=0;i<1024;i++)x+=w[i]*h[i];return x;}
static double head_run(const std::vector<float>& qW,const std::vector<float>&qb,const std::vector<float>&kW,const std::vector<float>&kb,float temp,int decide,const std::vector<int>&opts){auto t0=std::chrono::steady_clock::now();const float*hd=&hidden[(size_t)decide*1024];std::vector<float>q(256);for(int j=0;j<256;j++)q[j]=lin(&qW[(size_t)j*1024],hd,&qb[j]);volatile float sink=0;for(int oi:opts){const float*ho=&hidden[(size_t)oi*1024];float v=0;for(int j=0;j<256;j++)v+=lin(&kW[(size_t)j*1024],ho,&kb[j])*q[j];sink+=v/std::sqrt(256.f)/temp;}if(sink==1234567)std::fprintf(stderr,"%f",sink);return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t0).count();}
int main(int argc,char**argv){if(argc<6){fprintf(stderr,"usage: %s model head ids decide opt...\n",argv[0]);return 2;}RKLLMParam p=rkllm_createDefaultParam();p.model_path=argv[1];p.max_context_len=8192;p.max_new_tokens=1;p.skip_special_token=false;RKLLMCallback c{};c.result_callback=cb;LLMHandle h=nullptr;int ret=rkllm_init(&h,&p,&c);printf("init_ret=%d\n",ret);if(ret)return 3;std::ifstream fh(argv[2],std::ios::binary);std::vector<float>qW(256*1024),qb(256),kW(256*1024),kb(256);float temp;fh.read((char*)qW.data(),qW.size()*4);fh.read((char*)qb.data(),qb.size()*4);fh.read((char*)kW.data(),kW.size()*4);fh.read((char*)kb.data(),kb.size()*4);fh.read((char*)&temp,4);std::ifstream fi(argv[3]);std::vector<int32_t>ids;int x;while(fi>>x)ids.push_back(x);int decide=std::atoi(argv[4]);std::vector<int>opts;for(int i=5;i<argc;i++)opts.push_back(std::atoi(argv[i]));RKLLMInput in{};in.role="user";in.enable_thinking=false;in.input_type=RKLLM_INPUT_TOKEN;in.token_input.input_ids=ids.data();in.token_input.n_tokens=ids.size();RKLLMInferParam ip{};ip.mode=RKLLM_INFER_GET_LAST_HIDDEN_LAYER;ip.keep_history=0;ip.max_new_tokens=1;int warm=20,samples=50; const char* ew=getenv("WARMUP"); if(ew) warm=atoi(ew); const char* es=getenv("SAMPLES"); if(es) samples=atoi(es); for(int i=0;i<warm;i++){rkllm_clear_kv_cache(h,0,nullptr,nullptr);g_tokens=g_dim=0;ret=rkllm_run(h,&in,&ip,nullptr);if(ret||g_tokens!=(int)ids.size())fprintf(stderr,"warm_error=%d tokens=%d\n",ret,g_tokens);}printf("warmup_done=%d samples=%d input_tokens=%zu\n",warm,samples,ids.size());for(int i=0;i<samples;i++){auto c0=std::chrono::steady_clock::now();int cr=rkllm_clear_kv_cache(h,0,nullptr,nullptr);double clear=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-c0).count();auto t0=std::chrono::steady_clock::now();g_tokens=g_dim=0;ret=rkllm_run(h,&in,&ip,nullptr);double run=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t0).count();double head=head_run(qW,qb,kW,kb,temp,decide,opts);printf("sample=%d clear_ms=%.6f run_ms=%.6f head_ms=%.6f e2e_ms=%.6f clear_ret=%d run_ret=%d input_tokens=%zu hidden_tokens=%d dim=%d perf_prefill_ms=%.3f perf_mem_mb=%.3f\n",i,clear,run,head,clear+run+head,cr,ret,ids.size(),g_tokens,g_dim,g_prefill,g_mem);fflush(stdout);}rkllm_destroy(h);return 0;}
